{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "A \"classroom library\" would mean materials donated to, bought by, or otherwise acquired by an individual teacher and made available in the teacher's classroom to students in that teacher's classes.",
      "rationale": "Conveys the teacher's acquisition of materials, their classroom availability, and the limitation to students assigned to that teacher."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "A \"library collection\" would mean materials a school run by a local education agency (LEA) or a public charter school makes available to students. It would not include course curriculum materials or classroom libraries.",
      "rationale": "Identifies both covered school types and both exclusions."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "\"Materials\" would be defined broadly. It would include books, periodicals, newspapers, films, discs, videotapes, video games, applications, and subscription content in any form.",
      "rationale": "Conveys much of the definition but omits the expressly included manuscripts, prints, documents, microfilm, and cassettes."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would also add references to classroom libraries in subsections (a), (f), and (g) of Section 49-6-3803, next to existing references to library collections.",
      "rationale": "Identifies all three amended subsections and explains the addition of classroom libraries alongside library collections; the exact insertion wording is not necessary."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The bill would delete subsection (b) of Section 49-6-3803 and replace the first sentence of subsection (d).",
      "rationale": "Expressly identifies the subsection being deleted."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would delete subsection (b) of Section 49-6-3803 and replace the first sentence of subsection (d). Each local board of education and public charter school governing body would have to adopt a policy for developing and reviewing school library collections and for classroom libraries.",
      "rationale": "Identifies the replacement and conveys the required policy, responsible bodies, and coverage of both library types."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "First, it would need a procedure for teachers, or for parents and legal guardians of students with access to a classroom library, to review materials in that library and refer them for review and evaluation.",
      "rationale": "Conveys the required procedure, eligible participants, access condition, and review and referral functions."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Second, it would need a procedure giving those parents and guardians multiple chances during the school year to view the books in their student's classroom library.",
      "rationale": "Conveys repeated viewing opportunities throughout the school year for the previously identified parents and guardians."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Third, it would need a provision barring teachers from knowingly or intentionally getting around the library collection policy through a classroom library. One example is including materials that the local board, the charter school governing body, or the state textbook and instructional materials quality commission has found inappropriate for students' age and maturity. Another is including materials that the board or governing body has found unsuitable for, or inconsistent with, the school's educational mission.",
      "rationale": "Conveys the prohibition, required mental state, classroom-library mechanism, and both examples with the relevant decision-makers and standards."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill would take effect as soon as it becomes law.",
      "rationale": "Accurately conveys the effective date."
    }
  ]
}
